#include <vector>
#include <limits>
#include <omp.h>

int smallestOdd(std::vector<int> const& x) {
    int globalMin = std::numeric_limits<int>::max();

    #pragma omp parallel
    {
        int localMin = std::numeric_limits<int>::max();

        #pragma omp for nowait
        for (int i = 0; i < static_cast<int>(x.size()); ++i) {
            int v = x[i];
            if ((v & 1) != 0 && v < localMin) {
                localMin = v;
            }
        }

        #pragma omp critical
        {
            if (localMin < globalMin) globalMin = localMin;
        }
    }

    // If no odd number exists, return INT_MAX (sentinel).
    return globalMin;
}
